<?php $commentOrder = comment_order($_GET);
$comments = visible_comments((int)$artwork['id'], $commentOrder); ?>
<section class="prototype-panel artwork-comments" id="comments"><h2>Comments (<?= count($comments) ?>)</h2>
<form class="comment-sort" data-comment-sort method="get" action="/art/<?= (int)$artwork['id'] ?>#comments"><label>Comment order <select name="commentSort" aria-label="Comment order"><option value="oldest" <?= $commentOrder === 'oldest' ? 'selected' : '' ?>>Oldest first</option><option value="newest" <?= $commentOrder === 'newest' ? 'selected' : '' ?>>Newest first</option></select></label><button type="submit">Apply</button></form>
<?php if ($notice): ?><p class="notice" role="status"><?= e($notice) ?></p><?php endif; ?>
<?php if ($user): ?><form class="prototype-form comment-compose" action="/comment" method="post"><?= csrf_field() ?><input type="hidden" name="commentSort" value="<?= e($commentOrder) ?>"><input type="hidden" name="artwork" value="<?= (int)$artwork['id'] ?>"><label>Leave a comment<textarea aria-label="Leave a comment" name="body" maxlength="4000" rows="4" required></textarea></label><div class="comment-compose-footer"><p class="help">Profanity, suspicious advertising and links from untrusted accounts are held for admin review.</p><button>Post comment</button></div></form><?php else: ?><p><a href="/login">Sign in to join the conversation →</a></p><?php endif; ?>
<?php foreach ($comments as $comment): ?><article class="comment"><span class="comment-avatar" aria-hidden="true"><?= e(mb_strtoupper(mb_substr($comment['username'], 0, 1))) ?></span><div class="comment-content"><div class="comment-heading"><div class="comment-author"><strong><?= e($comment['username']) ?></strong><?php if ($comment['archived']): ?><span class="comment-archive-label">Archived</span><?php endif; ?></div><div class="comment-date"><?php render_time((int)$comment['created']); ?></div></div><p class="comment-body"><?= e($comment['body']) ?></p><?php if ($user && ($user['role'] === 'admin' || (int)$comment['owner_id'] === (int)$user['id'])): ?><div class="comment-controls"><form action="/comment/delete" method="post" data-confirm="Delete this comment?"><?= csrf_field() ?><input type="hidden" name="commentSort" value="<?= e($commentOrder) ?>"><input type="hidden" name="id" value="<?= (int)$comment['id'] ?>"><button class="quiet-button">Delete comment</button></form></div><?php endif; ?></div></article><?php endforeach; ?>
<?php if (!$comments): ?><p class="help">No published comments yet. Start the conversation.</p><?php endif; ?></section>
